input.command:
cat > /tmp/fix_q27.sql << 'EOF'
INSTALL spatial; LOAD spatial;
INSTALL httpfs; LOAD httpfs;
SET geometry_always_xy = true;

CREATE TABLE car AS
SELECT * FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/brazil-car-area-imovel/brazil_car_area_imovel.parquet');

CREATE TABLE trazo3 AS
SELECT * FROM read_parquet('https://data.source.coop/wri-data-lab/trazofields/trazo3-fields/trazo3_brazil_goias_2024.parquet');

CREATE TABLE facilities AS
SELECT * FROM read_parquet('https://data.source.coop/tristangruppwri/soft-commodity-infrastructure/facilities/BR_facilities.parquet');

CREATE TABLE input_list AS
SELECT * FROM read_csv_auto('/workspace/lists/goias-sample.csv');

-- Get municipality code from cod_imovel
CREATE TABLE resolved_parcels_with_code AS
SELECT DISTINCT
    il.cod_imovel,
    car.municipio,
    SUBSTRING(il.cod_imovel, 4, 7) as muni_code,
    car.num_area,
    car.geometry
FROM input_list il INNER JOIN car ON car.cod_imovel = il.cod_imovel
WHERE il.cod_imovel IS NOT NULL AND il.cod_imovel != '';

-- Get flagged parcels
CREATE TABLE parcel_envelope AS
SELECT ST_Envelope(ST_Union_Agg(geometry)) as env_geom FROM resolved_parcels_with_code;

CREATE TABLE fields_in_envelope AS
SELECT t.Id as field_id, t.deforestarea2124 as loss_2021_2024
FROM trazo3 t WHERE ST_Intersects(t.geometry, (SELECT env_geom FROM parcel_envelope));

CREATE TABLE flagged_parcels AS
SELECT DISTINCT rp.cod_imovel, rp.muni_code
FROM resolved_parcels_with_code rp
WHERE EXISTS (
    SELECT 1 FROM fields_in_envelope fie WHERE fie.loss_2021_2024 > 0
);

-- Q27: Membership candidates
CREATE TABLE q27_fixed AS
SELECT
    fp.cod_imovel,
    fp.muni_code as entity_id,
    COUNT(*) as evidence
FROM flagged_parcels fp
INNER JOIN facilities f ON f.entity_id = fp.muni_code
WHERE f.tier = 'membership_muni'
GROUP BY fp.cod_imovel, fp.muni_code;

COPY (SELECT cod_imovel, entity_id, CAST(evidence as FLOAT) as evidence FROM q27_fixed) TO '/workspace/answers/q27.csv' (FORMAT CSV, HEADER);

SELECT * FROM q27_fixed LIMIT 10;
EOF
